  const directory = dirname(databasePath);
  const temporaryPath = join(directory, `.${basename(databasePath)}.${process.pid}.${crypto.randomUUID()}.tmp`);
  try {
    await Bun.write(temporaryPath, `${JSON.stringify(database, null, 2)}\n`);
    await rename(temporaryPath, databasePath);
  } catch (error) {
    try {
      await Bun.file(temporaryPath).delete();
    } catch {}
    throw error;
  }
}

function parseFlags(tokens: string[], definitions: Record<string, true>): Record<string, string> {
  const result: Record<string, string> = {};
  for (let index = 0; index < tokens.length; index += 1) {
    const flag = tokens[index];
    if (!flag.startsWith("--") || definitions[flag] !== true) fail(`Unknown flag: ${flag}`);
    if (flag in result) fail(`Duplicate flag: ${flag}`);
    const value = tokens[++index];
    if (value === undefined || value.startsWith("--")) fail(`Missing value for ${flag}`);
    result[flag] = value;
  }
  return result;
}

function parseId(value: string | undefined): number {
  if (value === undefined || !/^[1-9]\d*$/.test(value)) fail("ID must be a positive integer");
  const id = Number(value);
  if (!Number.isSafeInteger(id)) fail("ID must be a positive integer");
  return id;
}

function normalizeTag(tag: string): string {
  return tag.trim().toLowerCase();
}

function localDate(date = new Date()): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

async function run(): Promise<unknown> {
  const [command, ...rest] = args;
  if (!command) fail("Missing command");

  if (command === "add") {
    const flags = parseFlags(rest, { "--title": true, "--tags": true, "--due": true });
    if (!("--title" in flags)) fail("Missing required flag: --title");
    const title = flags["--title"].trim();
    if (!title) fail("Title must not be empty");
    const due = flags["--due"];
    if (due !== undefined && !isDate(due)) fail("Due date must be a valid YYYY-MM-DD date");
    const tags = flags["--tags"] === undefined
      ? []
      : [...new Set(flags["--tags"].split(",").map(normalizeTag).filter(Boolean))];
    const database = await loadDatabase();
    const task: Task = {
      id: database.nextId,
      title,
      status: "open",
      createdAt: new Date().toISOString(),
      tags,
      ...(due === undefined ? {} : { due }),
    };
    database.nextId += 1;
    database.tasks.push(task);
    await saveDatabase(database);
    return task;
  }

  if (command === "list") {
    const flags = parseFlags(rest, { "--status": true, "--tag": true, "--overdue": true });
    const status = flags["--status"];
    if (status !== undefined && status !== "open" && status !== "done") fail("Status must be open or done");
    const overdue = flags["--overdue"];
    if (overdue !== undefined && !isDate(overdue)) fail("Overdue date must be a valid YYYY-MM-DD date");
    const tag = flags["--tag"] === undefined ? undefined : normalizeTag(flags["--tag"]);
    if (tag === "") fail("Tag must not be empty");
    const database = await loadDatabase();
    return database.tasks
      .filter((task) => status === undefined || task.status === status)
      .filter((task) => tag === undefined || task.tags.includes(tag))
      .filter((task) => overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
      .sort((a, b) => a.id - b.id);
  }

  if (command === "done") {
    if (rest.length !== 1) fail("Usage: done ID");
    const id = parseId(rest[0]);
    const database = await loadDatabase();
    const task = database.tasks.find((candidate) => candidate.id === id);
    if (!task) fail(`Task ${id} not found`);
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await saveDatabase(database);
    }
    return task;
  }

  if (command === "delete") {
    if (rest.length !== 1) fail("Usage: delete ID");
    const id = parseId(rest[0]);
    const database = await loadDatabase();
    const index = database.tasks.findIndex((task) => task.id === id);
    if (index < 0) fail(`Task ${id} not found`);
    const [task] = database.tasks.splice(index, 1);
    await saveDatabase(database);
    return task;
  }

  if (command === "stats") {
    if (rest.length !== 0) fail(`Unknown flag: ${rest[0]}`);
    const database = await loadDatabase();
    const today = localDate();
    const open = database.tasks.filter((task) => task.status === "open").length;
    const done = database.tasks.length - open;
    const overdue = database.tasks.filter((task) => task.status === "open" && task.due !== undefined && task.due < today).length;
    return { total: database.tasks.length, open, done, overdue };
  }

  fail(`Unknown command: ${command}`);
}

try {
  const result = await run();
  console.log(JSON.stringify(result));
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.error(message);
  console.log(JSON.stringify({ error: message }));
  process.exitCode = 1;
}

import { afterEach, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";

const cli = join(import.meta.dir, "cli.ts");
const directories: string[] = [];

afterEach(async () => {
  await Promise.all(directories.splice(0).map((directory) => rm(directory, { recursive: true, force: true })));
});

async function setup(): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), "taskboard-test-"));
  directories.push(directory);
  return join(directory, "board.json");
}

async function invoke(file: string, args: string[]) {
  const process = Bun.spawn([processExec(), "run", cli, ...args], {
    env: { ...Bun.env, TASKBOARD_FILE: file },
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(process.stdout).text(),
    new Response(process.stderr).text(),
    process.exited,
  ]);
  const lines = stdout.trim().split("\n");
  return { value: JSON.parse(stdout), stdout, stderr, exitCode, lines };
}

function processExec(): string {
  return Bun.which("bun")!;
}

describe("taskboard CLI", () => {
  test("persists tasks, normalizes tags, filters, and keeps IDs stable", async () => {
    const file = await setup();
    const first = await invoke(file, ["add", "--title", " First task ", "--tags", " Work,work, Urgent ", "--due", "2000-01-01"]);
    expect(first.exitCode).toBe(0);
    expect(first.lines).toHaveLength(1);
    expect(first.value).toMatchObject({ id: 1, title: "First task", status: "open", tags: ["work", "urgent"], due: "2000-01-01" });

    const second = await invoke(file, ["add", "--title", "Second", "--tags", "home"]);
    expect(second.value.id).toBe(2);
    const filtered = await invoke(file, ["list", "--status", "open", "--tag", "WORK", "--overdue", "2001-01-01"]);
    expect(filtered.value.map((task: { id: number }) => task.id)).toEqual([1]);

    expect((await invoke(file, ["delete", "1"])).exitCode).toBe(0);
    expect((await invoke(file, ["add", "--title", "Third"])).value.id).toBe(3);
    expect((await invoke(file, ["list"])).value.map((task: { id: number }) => task.id)).toEqual([2, 3]);
  });

  test("done is idempotent and stats reflect current state", async () => {
    const file = await setup();
    await invoke(file, ["add", "--title", "Old", "--due", "2000-01-01"]);
    await invoke(file, ["add", "--title", "Active"]);
    const first = await invoke(file, ["done", "2"]);
    const repeated = await invoke(file, ["done", "2"]);
    expect(repeated.value.completedAt).toBe(first.value.completedAt);
    expect((await invoke(file, ["stats"])).value).toEqual({ total: 2, open: 1, done: 1, overdue: 1 });
  });

  test("rejects invalid input and preserves malformed databases", async () => {
    const file = await setup();
    const invalidDate = await invoke(file, ["add", "--title", "Bad", "--due", "2025-02-29"]);
    expect(invalidDate.exitCode).not.toBe(0);
    expect(invalidDate.lines).toHaveLength(1);
    expect(invalidDate.value.error).toContain("Due date");

    await writeFile(file, "not json\n");
    const malformed = await invoke(file, ["list"]);
    expect(malformed.exitCode).not.toBe(0);
    expect(malformed.stderr).toContain("Malformed");
    expect(await readFile(file, "utf8")).toBe("not json\n");
  });

  test("unknown commands, flags, and missing tasks fail", async () => {
    const file = await setup();
    expect((await invoke(file, ["wat"])).exitCode).not.toBe(0);
    expect((await invoke(file, ["list", "--wat", "x"])).exitCode).not.toBe(0);
    expect((await invoke(file, ["done", "9"])).exitCode).not.toBe(0);
  });
});

